   "使用原住民族圖騰前，要先了解意義並取得部落同意，尊重文化。",
   "✅ 正確觀念：布袋戲是博大精深的中華表演藝術集大成！它融合了傳統雕刻工藝、刺繡服飾、古典南北管音樂、口白說書文學與高難度雜技操偶身段。2006 年臺灣更透過全民票選，將布袋戲選為最能代表臺灣精神的「意象第一名」！",
   "工藝起源：早期物資匱乏，匠師將破碎的彩色陶瓷碗盤、玻璃瓶洗淨，用特製鐵剪修剪成花瓣、龍鱗、羽毛碎片。",
   "「藍」指的是天然染料植物「藍草（大菁/木藍）」；「青」指的是從藍草中提煉發酵萃取出來、染在布料上經過氧化後呈現的「深藍色」。",
   "臺灣有許多傳統工藝：藍染是用植物（例如大菁）做成的藍色染料來染布；竹編是用竹子編成籃子、器具；交趾陶是色彩鮮豔的陶偶，常裝飾在廟宇的牆面和屋脊上。這些工藝取材自自然，記錄著先人的生活智慧。",
   "學習目標：走進古色古香的廟宇與工藝聚落，細細品味「交趾陶」水車堵捏塑與「剪黏」碗片碎嵌的建築裝飾智慧；親手探索植物「大菁」藍染防染圖紋的自然之美；精熟布袋戲五大行當的性格神韻與操偶動作精髓；跨越國界欣賞捷克懸絲偶、印尼皮影戲與日本文樂偶戲的精妙技藝，成為懂得守護與活化傳統文化的當代美學傳承者！",
   "$\\textcolor{#2e7d32}{\\textbf{表 2-III-1}}$ 掌握臺灣布袋戲（掌中戲）角色行當（生、旦、淨、末、丑）特徵與基本操偶身段，並拓展世界經典偶戲（懸絲偶、皮影戲、文樂）之多元美學視野。",
   "[ 布袋戲五大角色行當一覽 ]",
   "布袋戲又稱「掌中戲」，因為偶身除頭部、手足外，身體軀幹就像一個布袋，操偶師將食指插入偶頭、拇指與中指伸入兩隻偶臂進行操控。",
   "✅ 正確觀念：傳統文化正以驚人的生命力蛻變！臺灣的霹靂布袋戲與日本合作推出《東離劍遊紀》動漫，融合 3D 動態特效與現代搖滾樂，在全世界吸引了數百萬年輕粉絲，創造出百億元以上的國際文創奇蹟！",
   "2．皮影戲偶材質誤選塑膠：傳統正統皮影戲偶是用浸泡硝製的「牛皮或羊皮」刻製上色，具備透光半透明特性。",
   "特色：精巧絲線操控手腳頭身  特色：水牛皮精細鏤空雕刻雕花   特色：三人合力操縱一尊大木偶",
   "印尼的「Wayang Kulit（皮影戲）」利用水牛皮雕刻出繁複精緻的鏤空神話人物，在油燈照耀下投射在白色布幕上，是最古老的光影藝術典範！",
   "把剪紙、交趾陶、刺繡等傳統工藝加入現代設計，做成文具、飾品等文創商品，讓更多人認識並喜愛傳統文化。",
