   "【比較句怎麼造】A is taller than B.；Which is bigger, a dog or a cat? A dog is bigger.；Who is the tallest in your class?；as + 原級 + as 表示一樣：Tom is as tall as Ben.；只有兩個比較用比較級；三個以上用最高級。much 可加強比較級：much bigger。",
