   "【字詞基本功：短文注音與國字】段考常用短文的方式考注音和國字。形近字要靠字義分辨：「揪」有抓的意思，部首是手；「糾」有纏繞之意，部首是糸。常見易錯：再接再「厲」、「按」部就班、迫不及「待」、川流不「息」。；寫作時用錯字也會扣分，寫完要檢查一次。",
