   "【指示劑顏色整理】指示劑：酸性：中性：鹼性；石蕊試紙：藍變紅：不變色：紅變藍；酚酞：無色：無色：粉紅；紫色高麗菜汁：紅色系：紫色：藍綠色系；用一種試紙不變色，不能直接判斷是中性，要兩種都試。",
   "【酸鹼性和導電性的實驗安全】強酸、強鹼具有腐蝕性。不可用嘴嘗、不可用手碰，聞氣味要用手搧。實驗器材要清洗，不同溶液的電極要先擦乾，避免互相汙染。；砂糖水、酒精水不導電；食鹽水、醋、氫氧化鈉水溶液能導電。水溶液能不能導電，和酸鹼性是兩回事。",
   "【溶液濃度的簡單比較】同樣的水量，溶解的糖越多，糖水越濃。比較兩杯濃度時，可以比較「糖 ÷ 水」的值。50 公克水溶解 5 公克糖，和 100 公克水溶解 10 公克糖，濃度相同。實驗記錄時要寫清楚水量和溶質量。；把水蒸發掉，溶質會留下來，例如海水曬鹽。這也是把水溶液中的物質分離出來的方法。過濾只能分出沒有溶解的固體，已溶解的食鹽過濾不出來。",
   "酸和鹼混合會發生酸鹼中和，產物通常是水和鹽類。",
