   "【不同物質傳熱快慢】金屬傳熱快，木頭、塑膠、空氣傳熱慢。羽絨衣和棉被保暖，主要靠鎖住空氣。；在同樣室溫下，摸金屬比摸木頭冰，不是金屬溫度比較低，而是金屬把手上的熱傳走得快。",
   "【保溫瓶和生活節能】保溫瓶的設計分別擋下三種傳熱：；真空夾層：阻擋傳導和對流。；銀亮內壁：反射輻射。；軟木塞或塑膠蓋：減少傳導和蒸發。；夏天穿淺色衣服較涼爽，是因為淺色反射較多輻射。深色吸收多，冬天曬棉被也用得上這個原理。",
   "【熱脹冷縮要留縫】大多數物體受熱體積變大，遇冷變小。鐵軌接縫、橋梁伸縮縫、電線夏天比較鬆，都是這個原因。溫度計裡的液體也靠熱脹冷縮指示溫度。瓶蓋太緊可用熱水燙一下，金屬蓋膨脹就容易打開。",
