   "保溫瓶有兩層瓶壁，中間抽成真空，熱很難靠傳導和對流跑出去；瓶壁內側像鏡子一樣亮，可以把熱輻射反射回去；瓶蓋也能減少對流散熱。",
   "📌 題目情境：不鏽鋼真空保溫瓶為什麼能長效保溫？請說明「真空層」與「內膽鍍銀/鏡面拋光」分別阻斷了哪種熱傳播？",
   "(填空題) 煮湯時，鍋底的水受熱後體積膨脹、密度變 $\\underline{\\hspace{1.5cm}}$ 而向上浮起，上方較冷的水密度較 $\\underline{\\hspace{1.5cm}}$ 而向下沉降，這種熱傳播方式稱為 $\\underline{\\hspace{2cm}}$。",
   "$\\textcolor{#2196f3}{\\textbf{熱對流 (Thermal Convection)}}$ 是$\\textcolor{#2196f3}{\\textbf{液體與氣體（流體）}}$中最主要的熱傳播方式。當流體底部受熱時，受熱區域流體溫度升高、體積膨脹、密度變小而向上浮起；上方較冷、密度較大的流體則向下沉降補充，形成循環流動。",
   "$\\textcolor{#ff9800}{\\textbf{燒水壺加熱點在底部}}$：底部加熱使熱水上升、冷水下降，快速完成全壺對流沸騰；若從水面加熱，熱水只會留在表層，底下的水依舊冰冷。",
   "大多數物質受熱時微觀粒子運動加劇、間距拉大，呈現$\\textcolor{#e91e63}{\\textbf{受熱膨脹}}$；降溫時粒子振動減緩、間距縮小，呈現$\\textcolor{#2196f3}{\\textbf{遇冷收縮}}$。",
   "🌱 生活例子：凹下去的乒乓球放進熱水裡，球裡的空氣受熱膨脹，就會鼓回來。溫度計裡的液體也是靠熱脹冷縮來顯示溫度。",
   "解答：因為固體具有「熱脹冷縮」的性質。夏天高溫時鋼軌會受熱膨脹變長，預留空隙能提供膨脹伸縮的空間，防止鐵軌因擠壓變形彎曲而釀成出軌意外。",
