   "【鐵生鏽實驗的對照設計】鐵生鏽需要水和氧氣同時存在。實驗常有這些組別：；1. 水加空氣：會生鏽。；2. 只有乾燥空氣：不易生鏽。；3. 煮沸過的水加油封：不易生鏽（水中氧氣很少）。；4. 食鹽水：鏽得更快。；判讀時要比較「只差一個條件」的兩組。",
